import { BaseBearerTokenAuthenticationProvider } from '@microsoft/kiota-abstractions'
import { DefaultRequestAdapter } from '@microsoft/kiota-bundle'
import { KiotaClientFactory, MiddlewareFactory } from '@microsoft/kiota-http-fetchlibrary'
import { SessionAccessTokenProvider, UnauthorizedHandler } from './auth'
import { createWaveMpApiClient, type WaveMpApiClient } from './generated/waveMpApiClient'

/**
 * Creates the API client generated by Kiota from the OpenAPI document.
 * The web app is served by the WaveMP service itself, so the API lives on the same origin.
 * Requests carry the token of the current session (see auth.ts).
 */
export function createApiClient(baseUrl: string = window.location.origin): WaveMpApiClient {
    // The own middleware comes first; the default chain ends with the handler that sends the
    // request.
    const httpClient = KiotaClientFactory.create(undefined, [
        new UnauthorizedHandler(),
        ...MiddlewareFactory.getDefaultMiddlewares(),
    ])

    // DefaultRequestAdapter registers the JSON, text, form and multipart serializers.
    const adapter = new DefaultRequestAdapter(
        new BaseBearerTokenAuthenticationProvider(new SessionAccessTokenProvider(baseUrl)),
        undefined,
        undefined,
        httpClient,
    )
    adapter.baseUrl = baseUrl
    return createWaveMpApiClient(adapter)
}

export const apiClient = createApiClient()
